{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MAPLEMONK.Freakins_GRN_Factitems` AS SELECT PO_Code, CASE WHEN PO_Date IS NOT NULL AND PO_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', PO_Date) AS DATE) ELSE NULL END AS PO_Date, PO_Type, Category, Facility, GRN_Code, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END AS GRN_Date, Batch_Code, Vendor_Code, Vendor_Name, trim(Item_SkuCode) Item_SkuCode, GRN_Created_By, GRN_Invoice_No, Item_Type_Name, Item_Type_Size, Vendor_SkuCode, Facility Warehouse_Name, Grn_item_Status, Item_Type_Brand, Item_Type_Color, CASE WHEN GRN_Invoice_Date IS NOT NULL AND GRN_Invoice_Date <> \'\' THEN SAFE_CAST(PARSE_DATE(\'%Y-%m-%d\', GRN_Invoice_Date) AS DATE) ELSE NULL END AS GRN_Invoice_Date, Rejection_Reason, CASE WHEN Total_Quantity_Received <> \'\' THEN CAST(Total_Quantity_Received AS INT64) end AS Quantity_Received, CASE WHEN Quantity_Rejected <> \'\' THEN CAST(Quantity_Rejected AS INT64) end AS Quantity_Rejected, CASE WHEN Percentage_Rejection <> \'\' then CAST(Percentage_Rejection AS FLOAT64) end AS Percentage_Rejection, CASE WHEN Values_of_Goods_Received_with_taxes <> \'\' then CAST(Values_of_Goods_Received_with_taxes AS FLOAT64) end AS GRN_Received_Value_with_taxes, CASE WHEN Values_of_Goods_Received_without_taxes <> \'\' then CAST(Values_of_Goods_Received_without_taxes AS FLOAT64) end AS GRN_Received_Value_without_taxes, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATETIME) ELSE NULL END AS GRN_Received_Timestamp, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) THEN \'30-60\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) THEN \'60-90\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 120 DAY) THEN \'90-120\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 180 DAY) THEN \'120-180\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 270 DAY) THEN \'180-270\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 360 DAY) THEN \'270-360\' ELSE \'360+\' END AS Bucket, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' ELSE \'30+\' END AS Extra_Bucket, Putaway_Code, CASE WHEN Putaway_Created IS NOT NULL AND Putaway_Created <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Putaway_Created) AS DATE) ELSE NULL END AS Putaway_Date, FROM maplemonk.unicommerce_get_grn_report WHERE UPPER(Facility) like any (\'%DLDRK%\',\'%BHIWANDI%\');",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            